// Diagnostic only: genuine native output and the existing hybrid/core checks.
// No trial, installation, roots, new witnesses or production binding changes.
import assert from 'node:assert/strict';
import {compileScene} from '../../workbenches/furnished-house/scene.js';
import {bounds,dot,sub,segmentTriangle,EPS} from '../../workbenches/furnished-house/geometry.js';
import {sourceSurfaceSpan} from '../../src/content/source-fixed-cell.js';
import {createHybridSourceSupport} from '../../src/simulation/hybrid-source-support.js';
import {createOriginalSupportPorts,originalMaterialComponents} from '../../src/simulation/original-support-ports.js';
import {originalContactPatches} from '../../src/content/cornice-wall-contact-pilot.js';
import {createSourceQueryRegistry} from '../../src/runtime/source-query-registry.js';
export class PanelDiagnosticBoundary extends Error{constructor(code,detail){super(code+': '+detail);this.name='PanelDiagnosticBoundary';this.code=code;}}
const fail=(code,detail)=>{throw new PanelDiagnosticBoundary(code,detail);},same=(a,b)=>JSON.stringify(a)===JSON.stringify(b),on=(point,ts)=>ts.some(t=>segmentTriangle(point,point,t)!==null);
export function createPanelDiagnosticOwner(parts){
  const byId=new Map(parts.map(p=>[p.id,p])),pins=[],events=[];let working=null,closed=false;
  const query=createSourceQueryRegistry({navigation:{placeId:'two-panel-diagnostic',surfaces:[{id:'unused-terrain',terrain:true,height:0,polygons:[[[0,0],[1,0],[1,1],[0,1]]]}],ceilings:[],portals:[],blockers:[]},parts:parts.map(p=>({id:p.id,carrierId:p.ownerId,physical:true,closed:p.closed,bounds:bounds(p.triangles.flat())})),shapeForPart:id=>({triangles:byId.get(id).triangles,closed:byId.get(id).closed})});
  const costs=()=>{const q=query.metrics(),w=working||{shapes:0,triangles:0},total={shapes:q.cachedShapes+w.shapes+24,triangles:q.cachedTriangles+w.triangles+8192};if(total.shapes>192||total.triangles>65536)fail('COMBINED_DIAGNOSTIC_GEOMETRY_BOUND',JSON.stringify(total));return {query:q,working:{...w},fallbackReserve:{shapes:24,triangles:8192},combinedReserved:total};};
  const reserve=(id,ts)=>{const q=query.metrics(),exists=pins.some(p=>p.shape.triangles===ts);if(!exists&&(q.cachedShapes+1+(working?.shapes||0)+24>192||q.cachedTriangles+ts.length+(working?.triangles||0)+8192>65536))fail('COMBINED_DIAGNOSTIC_GEOMETRY_BOUND',id);const p=query.reserveSourceGeometry(id,ts);pins.push(p);return p;};
  for(const p of parts){pins.push(query.pinOriginal(p.id));}events.push({phase:'originals-borrowed',...costs()});
  return {query,reserve,events,costs,beginWorking(){if(working||closed)fail('DIAGNOSTIC_WORKING_LIFETIME','An existing reservation is live');working={shapes:16,triangles:4096};events.push({phase:'working-reserved',...costs()});return ()=>{working=null;events.push({phase:'working-released',...costs()});};},dispose(){if(closed)return;closed=true;working=null;for(const p of pins)p.release();pins.length=0;query.dispose();events.push({phase:'disposed',...costs()});}};
}

export function inspectThickPanelPort({parts,surface,sourceBond,capturedBond,thermalProjection,grid,sourceRevision,owner,counter,limits,onGeometry=()=>{}}){
  const parent=parts.find(p=>p.id===sourceBond.parent.partId),child=parts.find(p=>p.id===sourceBond.child.partId);if(!parent||!child||parts.length!==2)fail('TWO_FIXED_ORIGINAL_PARTS','One cold parent and one child required');
  if(surface.nativePartId!==child.id||surface.sourceCarrierId!==child.ownerId||surface.triangles.length!==2||surface.kind!=='wall'||!(surface.thickness>0)||surface.solidTriangles?.length)fail('SAVED_NATIVE_PANEL_REQUIRED',child.id);
  const span=sourceSurfaceSpan(surface,grid),canonicalCells=span.min.reduce((n,v,i)=>n*(span.max[i]-v+1),1);if(counter.canonicalCells+canonicalCells>limits.canonicalCells)fail('CANONICAL_CHILD_CELL_BOUND',child.id);
  const endpoint=e=>{const part=parts.find(p=>p.id===e.partId),bp=capturedBond[e===sourceBond.parent?'parent':'child'].bindingPlan;if(!bp?.cell||!part||!part.components.find(c=>c.id===e.component)?.primitives.includes(e.primitive)||!on(e.point,[part.triangles[e.primitive]])||e.selector&&e.point.some((v,i)=>v<e.selector.min[i]-EPS||v>e.selector.max[i]+EPS))fail('FIXED_ORIGINAL_WITNESS_REQUIRED',e.partId);return {partId:e.partId,point:[...e.point],primitives:[e.primitive],sourceSurfaceId:part.ownerId+'/part/'+part.globalIndex+'/'+bp.suffix,cell:[...bp.cell],nativeRecordId:null};};
  const bond={id:sourceBond.id,kind:sourceBond.kind,direction:sourceBond.direction,sourceSha256:sourceBond.proofRef.sha256,parent:endpoint(sourceBond.parent),child:endpoint(sourceBond.child)};
  if(!same(bond.child.sourceSurfaceId,surface.id)||bond.child.cell.some((v,i)=>v<span.min[i]||v>span.max[i]))fail('CAPTURED_SOURCE_CELL_OR_SURFACE',child.id);
  const definition={parts:parts.map(p=>({id:p.id,ownerId:p.ownerId})),bonds:[bond],anchors:[],requirements:[],approvedMounts:[]};let scene,graph,stage,releaseWorking;
  try{
    owner.reserve('diagnostic/input/'+surface.id,surface.triangles);releaseWorking=owner.beginWorking();if(counter.compilerCalls>=limits.compilerCalls)fail('NATIVE_COMPILER_ALLOWANCE',sourceBond.id);counter.compilerCalls++;counter.canonicalCells+=canonicalCells;
    scene=compileScene({version:1,runtimeAdapterVersion:1,implicitGround:false,gridOrigin:grid.origin,thermalCell:grid.pitch,internalHybrid:true,hybridSourceRevision:sourceRevision,surfaces:[surface],openings:[],items:[],furnitureParts:[],stores:[]});
    const records=[...scene.index.surfaces.values()];if(records.length>canonicalCells||records.some(r=>r.triangles.length>14||(r.solidTriangles||r.triangles).length>112))fail('NATIVE_OUTPUT_GEOMETRY_BOUND',sourceBond.id);
    for(const r of records){owner.reserve('diagnostic/thermal/'+r.id,r.triangles);if(r.solidTriangles&&r.solidTriangles!==r.triangles)owner.reserve('diagnostic/physical/'+r.id,r.solidTriangles);}
    onGeometry({sourceBondId:sourceBond.id,diagnosticOnly:true,sourceRevision,grid,sourceSurface:surface,records:records.map(r=>({id:r.id,sourceSurfaceId:r.sourceSurfaceId,sourceCarrierId:r.sourceCarrierId,nativePartId:r.nativePartId,sourceCell:r.sourceCell,kind:r.kind,normal:r.normal,thickness:r.thickness,material:r.material,area:r.area,bounds:r.bounds,triangles:r.triangles,solidTriangles:r.solidTriangles??null,closedShape:r.closedShape??null,fuelId:r.fuelId??null})),initialFuel:scene.initialFuel});
    // An additional existing initialization exposes its own canonicalization;
    // only the genuine hybrid prepare below performs an evaluate call.
    const core=createOriginalSupportPorts({...definition,parts:parts.map(p=>({id:p.id,ownerId:p.ownerId,triangles:p.triangles}))});let initialized;
    try{initialized=core.bindings()[0];}finally{core.dispose();}
    const canonicalization={};for(const side of ['parent','child']){const before=sourceBond[side],after=initialized[side];assert.deepEqual(after.originalWitness,before.point);if(after.primitive!==before.primitive||after.component!==before.component)fail('INITIAL_ORIGINAL_IDENTITY_CHANGED',side);canonicalization[side]={authoredPoint:before.point,initializedPoint:after.point,delta:after.point.map((v,i)=>v-before.point[i]),distance:after.distance,pointChanged:!same(before.point,after.point),originalPrimitive:before.primitive,originalComponent:before.component};}
    const distance=dot(sub(sourceBond.child.point,surface.triangles[0][0]),surface.normal),projectedPoint=sourceBond.child.point.map((v,i)=>v-distance*surface.normal[i]),components=originalMaterialComponents(child.triangles);let diagnosticLineagePredicates=0;
    const native=records.map(r=>{const body=r.solidTriangles||r.triangles,matched=components.map(c=>({component:c.id,primitives:c.primitives.filter(i=>{diagnosticLineagePredicates++;return originalContactPatches(body,child.triangles[i]).length;})})).filter(c=>c.primitives.length);return {recordId:r.id,sourceSurfaceId:r.sourceSurfaceId,sourceCell:r.sourceCell,partId:r.nativePartId,thermalTriangles:r.triangles.length,physicalTriangles:body.length,lineage:matched,componentMatches:matched.length===1&&matched[0].component===sourceBond.child.component,primitiveMatches:matched.length===1&&matched[0].primitives.includes(sourceBond.child.primitive),capturedCellMatches:same(r.sourceCell,bond.child.cell),capturedSurfaceMatches:r.sourceSurfaceId===bond.child.sourceSurfaceId,authoredPointInThermal:on(sourceBond.child.point,r.triangles),projectedPointInThermal:on(projectedPoint,r.triangles),authoredPointInPhysical:on(sourceBond.child.point,body),initializedPointInPhysical:on(initialized.child.point,body)};});
    graph=createHybridSourceSupport({scene,querySource:owner.query,definition});if(counter.originalPortEvaluations>=limits.originalPortEvaluations)fail('ORIGINAL_PORT_EVALUATION_ALLOWANCE',sourceBond.id);counter.originalPortEvaluations++;stage=graph.prepare(records,null,new Set([child.ownerId]));const result=stage.result,port=result.ports.find(p=>p.id===bond.id),candidate=native.filter(r=>r.componentMatches&&r.primitiveMatches&&r.capturedCellMatches&&r.capturedSurfaceMatches);assert.equal(result.supportedIds.length,0);assert.equal(result.births.length,0);
    const summary={id:sourceBond.id,status:port?.live?'REPRESENTABLE_UNDER_CAPTURED_CELL':'UNREPRESENTABLE_UNDER_CAPTURED_CELL',interpretation:'Disposable two-part physical-port diagnostic, not rooted support or production approval',sourceWitness:{parent:sourceBond.parent,child:sourceBond.child},canonicalization,capturedSourceCell:bond.child.cell,capturedSourceSurfaceId:bond.child.sourceSurfaceId,thermalProjection,projectedPoint,native,diagnosticLineagePredicates,hybridCoreResult:result,diagnosticPort:port,candidateRecordIds:candidate.map(r=>r.recordId),inputQuantity:surface.fuelAmount,inputFuelClass:surface.fuelClass,inputFinish:surface.finish??null,outputQuantity:scene.initialFuel,outputFuelRecords:scene.fuels.size,outputFuelAmounts:[...scene.fuels.values()].map(f=>({id:f.id,amount:f.amount,initial:f.initial,cls:f.cls})),canonicalSourceCells:canonicalCells,nativeRecords:records.length,allocatedAirCells:scene.cells.size,anchors:[],rootedSupport:'NOT_ESTABLISHED_NO_ROOTS',worldInstalled:false,futureProductionNativeIds:{parent:null,child:null},resources:owner.costs()};
    return summary;
  }finally{stage?.dispose();graph?.dispose();if(scene){scene.index.surfaces.clear();scene.index.bins.clear();for(const k of ['cells','fuels','items','parts','sourceDefinitions'])scene[k].clear();}releaseWorking?.();}
}

import test,{after} from 'node:test';
import assert from 'node:assert/strict';
import {boxTriangles} from '../fixtures/regional-query-data.mjs';
import {nativePanel} from '../../src/content/map-source-shapes.js';
import {originalMaterialComponents} from '../../src/simulation/original-support-ports.js';
import {sourceSurfaceSpan} from '../../src/content/source-fixed-cell.js';
import {createPanelDiagnosticOwner,inspectThickPanelPort} from '../../tools/review/thick-panel-port-diagnostic.mjs';
import {sceneCompileDiagnostics} from '../../workbenches/furnished-house/scene.js';
import {trialDiagnostics,limitDiagnosticTrialSteps} from '../../workbenches/furnished-house/simulation.js';
const grid={origin:[0,0,0],pitch:[.5,1.06,.5]},results=[],limits={compilerCalls:4,canonicalCells:64,originalPortEvaluations:4};limitDiagnosticTrialSteps(64);
function fixture(){const parts=[{id:'parent',ownerId:'fixture::parent',globalIndex:0,closed:true,triangles:boxTriangles([.42,-.125,.125],[.58,.125,1.125])},{id:'child',ownerId:'fixture::child',globalIndex:1,closed:true,triangles:boxTriangles([.42,.125,.125],[.58,2.125,1.125])}];for(const p of parts)p.components=originalMaterialComponents(p.triangles);
  const surface={...nativePanel({quantityBasis:{rule:'wall-area'},physicalMaterial:'timber',fuelAmount:0},parts[1].triangles),id:'fixture::child/part/1/plane',sourceCarrierId:'fixture::child',nativePartId:'child',material:'timber',fuelClass:'clapboard',fuelAmount:2,finish:null},end=(partId,primitive)=>({partId,ownerId:'fixture::'+partId,component:0,primitive,point:[.42,.125,.375]}),sourceBond={id:'thick-bearing',kind:'bearing-face',direction:'parent-to-child',proofRef:{sha256:'1'.repeat(64)},parent:end('parent',6),child:end('child',8)},capturedBond=structuredClone(sourceBond);capturedBond.parent.bindingPlan={suffix:'plane',cell:[1,0,0]};capturedBond.child.bindingPlan={suffix:'plane',cell:[1,0,0]};return {parts,surface,sourceBond,capturedBond,grid,sourceRevision:'a'.repeat(64),thermalProjection:{status:'SYNTHETIC_CONTROL'}};
}
after(()=>console.log('TWO_PANEL_SYNTHETIC '+JSON.stringify({results,compiler:sceneCompileDiagnostics(),trial:trialDiagnostics(),actualSavedNativeDiagnostics:0,actualSourceTransforms:0})));
test('a genuine thick native panel resolves its original physical point with a cold parent and no roots',()=>{const input=fixture(),owner=createPanelDiagnosticOwner(input.parts),counter={compilerCalls:0,canonicalCells:0,originalPortEvaluations:0};let summary;
  try{summary=inspectThickPanelPort({...input,owner,counter,limits,onGeometry:g=>{assert.ok(g.records.some(r=>r.solidTriangles.length>r.triangles.length));assert.equal(g.records.every(r=>r.nativePartId==='child'),true);}});assert.equal(summary.status,'REPRESENTABLE_UNDER_CAPTURED_CELL');assert.equal(summary.diagnosticPort.live,true);assert.equal(summary.hybridCoreResult.supportedIds.length,0);assert.equal(summary.futureProductionNativeIds.child,null);assert.ok(summary.native.some(r=>r.authoredPointInPhysical&&!r.authoredPointInThermal));assert.equal(counter.compilerCalls,1);assert.equal(counter.originalPortEvaluations,1);assert.ok(counter.canonicalCells<=64);}finally{owner.dispose();results.push({kind:'thick-positive',summary,counter,after:owner.costs()});}
});
test('a fixed wrong in-loop cell cannot borrow a different native point owner',()=>{const input=fixture(),span=sourceSurfaceSpan(input.surface,grid);input.capturedBond.child.bindingPlan.cell=[1,span.max[1],span.max[2]];const owner=createPanelDiagnosticOwner(input.parts),counter={compilerCalls:0,canonicalCells:0,originalPortEvaluations:0};let summary;
  try{summary=inspectThickPanelPort({...input,owner,counter,limits});assert.equal(summary.status,'UNREPRESENTABLE_UNDER_CAPTURED_CELL');assert.equal(summary.diagnosticPort.live,false);assert.ok(summary.native.some(r=>r.authoredPointInPhysical&&!r.capturedCellMatches));assert.equal(summary.futureProductionNativeIds.child,null);}finally{owner.dispose();results.push({kind:'wrong-captured-cell',summary,counter,after:owner.costs()});}
});
test('named source/cell and compiler bounds stop before another native compile',()=>{const input=fixture(),owner=createPanelDiagnosticOwner(input.parts),counter={compilerCalls:0,canonicalCells:0,originalPortEvaluations:0},before=sceneCompileDiagnostics().calls;
  try{input.capturedBond.child.bindingPlan.cell=[1,99,0];assert.throws(()=>inspectThickPanelPort({...input,owner,counter,limits}),e=>e.code==='CAPTURED_SOURCE_CELL_OR_SURFACE');assert.equal(sceneCompileDiagnostics().calls,before);input.capturedBond.child.bindingPlan.cell=[1,0,0];assert.throws(()=>inspectThickPanelPort({...input,owner,counter,limits:{...limits,compilerCalls:0}}),e=>e.code==='NATIVE_COMPILER_ALLOWANCE');assert.equal(sceneCompileDiagnostics().calls,before);}finally{owner.dispose();results.push({kind:'precompile-bounds',counter,after:owner.costs()});}
});

import {createOriginalSupportPorts,originalMaterialComponents} from './original-support-ports.js';
import {originalContactPatches} from '../content/cornice-wall-contact-pilot.js';
import {segmentTriangle,triangleArea} from '../../workbenches/furnished-house/geometry.js';

// Corrected original-port semantics over bounded borrowed source geometry.
// Only IDs/results survive solves; current fragment meshes are temporary.
export function createHybridSourceSupport({scene,querySource,definition}){
  const pins=[],parts=[],byPart=new Map(),components=new Map();let closed=false,revision=0,state=null,fixed=new Map(),configured=null;
  const live=()=>{if(closed)throw Error('Hybrid support disposed');};
  try{for(const spec of definition.parts){const pin=querySource.pinOriginal(spec.id);pins.push(pin);const p={...spec,triangles:pin.shape.triangles};parts.push(p);byPart.set(p.id,p);components.set(p.id,originalMaterialComponents(p.triangles));}
    if(parts.reduce((n,p)=>n+p.triangles.length,0)>65536)throw Error('Hybrid originals exceed combined source budget');
    function originalCore(bindings){return createOriginalSupportPorts({...definition,parts,bonds:definition.bonds.map(b=>({...b,parent:{...b.parent,cell:undefined,...bindings.get(b.id+'/parent')},child:{...b.child,cell:undefined,...bindings.get(b.id+'/child')}}))});}
    function fragments(records,regional,wholeClaims,coldPieces){
      const coldByPart=new Map();for(const piece of coldPieces){if(!coldByPart.has(piece.partId))coldByPart.set(piece.partId,[]);coldByPart.get(piece.partId).push(piece);}
      const out=[];for(const p of parts){const rs=records.filter(b=>!b.queryOnly&&b.nativePartId===p.id&&b.intact),cs=components.get(p.id);
        for(const b of rs){const ts=b.solidTriangles||b.triangles;if(!ts?.length||ts.some(t=>!Number.isFinite(triangleArea(t))||!(triangleArea(t)>0)))throw Error('Finite positive current support geometry required');const matched=cs.map(c=>({component:c.id,primitives:c.primitives.filter(i=>originalContactPatches(ts,p.triangles[i]).length)})).filter(c=>c.primitives.length);if(matched.length!==1)throw Error('Native original component/face lineage unproved');out.push({id:b.id,recordId:b.id,partId:p.id,ownerId:p.ownerId,mode:'native',cell:b.sourceCell,triangles:ts,solidTriangles:ts,...matched[0]});}
        if(regional?.has(p.id)&&regional.touched(p.id)){
          const groups=new Map();for(const piece of coldByPart.get(p.id)||[]){const component=cs.find(c=>c.primitives.includes(piece.primitive));if(!component)throw Error('Cold source primitive lineage missing');const key=component.id+'/'+piece.cell.join(',');if(!groups.has(key))groups.set(key,{id:'cold:'+p.id+'@'+key,partId:p.id,ownerId:p.ownerId,component:component.id,mode:'cold',cell:piece.cell,originalPrimitives:[],triangles:[]});const g=groups.get(key);g.originalPrimitives.push(...piece.triangles.map(()=>piece.primitive));g.triangles.push(...piece.triangles);}
          // One original component/cell can contain disconnected survivors.
          // Keep current islands separate; the existing material-contact core
          // can join touching fragments, but no shared ID may bridge a gap.
          for(const g of groups.values())for(const island of originalMaterialComponents(g.triangles)){const {originalPrimitives,...fragment}=g;out.push({...fragment,id:g.id+'/island-'+island.id,triangles:island.primitives.map(i=>g.triangles[i]),primitives:[...new Set(island.primitives.map(i=>originalPrimitives[i]))]});}
        }else if(!wholeClaims.has(p.ownerId)&&!rs.length)for(const c of cs)out.push({id:'cold:'+p.id+'/'+c.id,partId:p.id,ownerId:p.ownerId,component:c.id,mode:'cold',primitives:c.primitives,triangles:c.primitives.map(i=>p.triangles[i])});
      }return out;
    }
    function solve(records,regional,wholeClaims,nextFixed=new Map(fixed)){
      const evaluate=coldPieces=>{const fs=fragments(records,regional,wholeClaims,coldPieces),basis=originalCore(new Map());try{
        for(const b of basis.bindings())for(const side of ['parent','child']){const key=b.id+'/'+side;if(nextFixed.has(key))continue;const endpoint=b[side],authored=definition.bonds.find(v=>v.id===b.id)[side];if(!authored.sourceSurfaceId||!authored.cell)throw Error('Fixed source surface/cell lineage required');const candidates=fs.filter(f=>f.mode==='native'&&f.partId===endpoint.partId&&f.component===endpoint.component&&f.primitives.includes(endpoint.primitive)&&JSON.stringify(f.cell)===JSON.stringify(authored.cell)&&records.find(r=>r.id===f.recordId)?.sourceSurfaceId===authored.sourceSurfaceId);if(candidates.length>1)throw Error('Ambiguous fixed native support owner');if(candidates.length===1)nextFixed.set(key,{nativeRecordId:candidates[0].recordId,cell:[...authored.cell]});}
      }finally{basis.dispose();}
      const core=originalCore(nextFixed);try{return {result:core.evaluate({revision,fragments:fs}),fixed:nextFixed};}finally{core.dispose();}};
      return parts.some(p=>regional?.has(p.id)&&regional.touched(p.id))?regional.withPieces(evaluate):evaluate([]);
    }
    const api={nodes:new Map(),links:new Map(),
      configure(fn){configured=fn;},
      prepare(records,regional,wholeClaims){live();const expected=revision,next=solve(records,regional,wholeClaims),ids=records.filter(b=>!b.queryOnly).map(b=>b.id);let done=false;return {result:next.result,validate(){live();if(done||revision!==expected)throw Error('Stale support stage');},commit(){this.validate();fixed=next.fixed;state=next.result;for(const id of ids)api.nodes.set(id,scene.index.surfaces.get(id));revision++;done=true;},dispose(){done=true;}};},
      sourcesAdded(result){live();for(const b of result.boundaries)api.nodes.set(b.id,b);},
      unsupported(){live();if(!configured)return [];const current=configured();const solved=solve(current.records,current.regional,current.wholeClaims);fixed=solved.fixed;state=solved.result;return state.unrootedIds.flatMap(id=>{const b=scene.index.surfaces.get(id);return b?.intact&&!b.queryOnly?[b]:[];});},
      pendingSources:()=>[],snapshot:()=>state,rootingEvidence:()=>({originalPorts:true,approvedMounts:definition.approvedMounts||[]}),
      diagnostics:()=>({productionEnabled:false,originalParts:parts.length,originalTriangles:parts.reduce((n,p)=>n+p.triangles.length,0),fixedNativePorts:fixed.size,revision,unresolvedBindings:state?.unresolvedBindings||[],retainedCurrentMeshes:0}),
      dispose(){if(closed)return;closed=true;for(const p of pins)p.release();pins.length=0;parts.length=0;byPart.clear();components.clear();fixed.clear();api.nodes.clear();state=null;configured=null;}
    };return api;
  }catch(error){for(const p of pins)p.release();throw error;}
}

// Disabled source support pilot. No world, fuel, renderer or clock ownership.
import * as T from '../runtime/three.js';
import {bounds,segmentTriangle,triangleArea,cross,sub} from '../../workbenches/furnished-house/geometry.js';
import {supportSurfacesTouch} from '../../workbenches/furnished-house/support.js';
import {sweptCylinderClear} from '../runtime/collision.js';
import {SOURCE_SUPPORT_TOLERANCE} from './source-support-calculations.js';

const vector=p=>Array.isArray(p)&&p.length===3&&p.every(Number.isFinite),key=p=>p.join(','),freeze=v=>{if(v&&typeof v==='object'&&!Object.isFrozen(v)){for(const x of Object.values(v))freeze(x);Object.freeze(v);}return v;};
const normal=t=>{const n=cross(sub(t[1],t[0]),sub(t[2],t[0])),l=Math.hypot(...n);return n.map(v=>v/l);};
const shape=ts=>({triangles:ts,solidTriangles:ts,bounds:bounds(ts.flat()),normal:normal(ts[0]),kind:'wall',thickness:0});
const inside=(p,ts)=>!sweptCylinderClear({x:p[0],y:p[2]},{x:p[0],y:p[2]},0,p[1],p[1],{triangles:ts,closed:true});
const closest=(p,t)=>new T.Triangle(...t.map(v=>new T.Vector3(...v))).closestPointToPoint(new T.Vector3(...p),new T.Vector3()).toArray();
const distance=(a,b)=>Math.hypot(...a.map((v,i)=>v-b[i]));
export const ORIGINAL_SUPPORT_LIMITS=Object.freeze({parts:14000,bonds:20000,fragments:65536,triangles:400000});

export function originalMaterialComponents(triangles){
  const edgeMap=new Map(),links=triangles.map(()=>[]),material=[];
  for(const [i,t]of triangles.entries()){
    if(!Array.isArray(t)||t.length!==3||!t.every(vector))throw Error('Finite original physical triangles required');const area=triangleArea(t);
    // Exact repeated coordinates prove an empty face. Keep its raw slot/ID,
    // but exclude even its zero-length edges from material topology.
    if(area===0&&t.some((a,j)=>t.some((b,k)=>j<k&&a.every((v,n)=>v===b[n]))))continue;
    if(!Number.isFinite(area)||!(area>0))throw Error('Finite original physical triangles required');material.push(i);
    for(let j=0;j<3;j++){const edge=[key(t[j]),key(t[(j+1)%3])].sort().join('|');if(!edgeMap.has(edge))edgeMap.set(edge,[]);edgeMap.get(edge).push(i);}
  }
